SELECT *
FROM t_game_round
WHERE provider_code = #{providerCode}
      AND deleted = FALSE
      AND create_time::DATE = #{date}
ORDER BY create_time

SELECT COALESCE(SUM(weighted_turnover), 0)
FROM t_game_round
WHERE player_id = #{playerId}
      AND tenant_id = #{tenantId}
      AND status = 2
      AND deleted = FALSE
